import { useParams } from "react-router-dom";
import { useState, useEffect } from "react";
import axios from "axios";

const videos = [
  {
    id: 1,
    title: "Cách làm web như YouTube",
    channel: "Lập Trình Với GPT",
    views: "1.2M lượt xem",
    thumbnail: "https://i.ytimg.com/vi/3qBXWUpoPHo/maxresdefault.jpg",
    src: "https://www.w3schools.com/html/mov_bbb.mp4",
  },
  {
    id: 2,
    title: "Học React siêu nhanh",
    channel: "Code Dạo Kênh",
    views: "300K lượt xem",
    thumbnail: "https://i.ytimg.com/vi/LNnBvJbnxOc/maxresdefault.jpg",
    src: "https://www.w3schools.com/html/movie.mp4",
  },
];

function WatchPage() {
  const { id } = useParams();
  const video = videos.find((v) => v.id === parseInt(id));

  const [suggested, setSuggested] = useState([]);
  const [likes, setLikes] = useState(0);
  const [dislikes, setDislikes] = useState(0);
  const [comments, setComments] = useState([
    "Video rất hữu ích!",
    "Cảm ơn bạn đã chia sẻ.",
  ]);
  const [newComment, setNewComment] = useState("");

  useEffect(() => {
    axios
      .get("https://jsonplaceholder.typicode.com/photos?_limit=5")
      .then((res) => setSuggested(res.data))
      .catch((err) => console.error("Lỗi API", err));
  }, []);

  const handleCommentSubmit = (e) => {
    e.preventDefault();
    if (newComment.trim() === "") return;
    setComments([newComment, ...comments]);
    setNewComment("");
  };

  if (!video)
    return <div className="p-4 text-red-600">Video không tồn tại.</div>;

  return (
    <div className="p-4 grid grid-cols-1 lg:grid-cols-3 gap-4">
      <div className="lg:col-span-2">
        <video controls src={video.src} className="w-full rounded" />
        <div className="mt-4">
          <h1 className="text-2xl font-bold">{video.title}</h1>
          <p className="text-sm text-gray-500">
            {video.channel} • {video.views}
          </p>

          <div className="flex gap-4 mt-2">
            <button
              onClick={() => setLikes(likes + 1)}
              className="px-3 py-1 bg-green-100 rounded hover:bg-green-200"
            >
              👍 {likes}
            </button>
            <button
              onClick={() => setDislikes(dislikes + 1)}
              className="px-3 py-1 bg-red-100 rounded hover:bg-red-200"
            >
              👎 {dislikes}
            </button>
          </div>

          <div className="mt-6">
            <h2 className="font-semibold text-lg mb-2">Bình luận</h2>
            <form onSubmit={handleCommentSubmit} className="mb-4">
              <input
                type="text"
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                placeholder="Viết bình luận..."
                className="w-full border px-3 py-2 rounded"
              />
            </form>
            <div className="space-y-2">
              {comments.map((cmt, index) => (
                <div key={index} className="bg-gray-100 p-2 rounded">
                  {cmt}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Suggested videos từ API */}
      <div>
        <h2 className="text-lg font-semibold mb-2">Gợi ý video</h2>
        <div className="space-y-4">
          {suggested.map((v) => (
            <div key={v.id} className="flex gap-2">
              <img
                src={v.thumbnailUrl}
                alt="thumb"
                className="w-20 h-14 rounded object-cover"
              />
              <div>
                <h3 className="font-semibold text-sm line-clamp-2">
                  {v.title}
                </h3>
                <p className="text-xs text-gray-500">Video demo</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default WatchPage;
